func fbWords(ans *port.Cells, id int32, n int32, cp int32, osd int32, script int32, sconf int32) int32 {
	// An answer of `n` words of three letters of the code point `cp`, one line each; `script` and `sconf` are what OSD said (0: nothing).
	var at int32 = oil.OilTessBegin(ans, id, 3, 0, 0, 0, 0, 0, osd, script, sconf, 0, 0)
	var k int32 = 0
	for k < n {
		oil.OilLine(ans, at, 10, 20+(k*60), 200, 40, 0, 1, -1, 0, 10, 55+(k*60), 210, 55+(k*60), 14, 14, 6, 0, 0, 0, 0, 0, 0, 0, 0, 0)
		k += 1
	}
	k = 0
	for k < n {
		var w int32 = oil.OilWord(ans, at, 10, 20+(k*60), 200, 40, k, 760, 0, 0, -1, 1)
		oil.OilWordCp(ans, at, w, cp)
		oil.OilWordCp(ans, at, w, cp)
		oil.OilWordCp(ans, at, w, cp)
		k += 1
	}
	oil.OilEnd(ans, at)
	return at
}

