func oneRequest(r *port.Cells, id int32) int32 {
	var at int32 = plan.RqOcr(r, id, 7, 3, 1, 0, 0, 0, 0)
	plan.RqOcrLang(r, 101, 110, 103, 0)
	plan.RqOcrEnd(r, at)
	return at
}

func engineAfter(id int32, routed int32) int32 {
	var r *port.Cells = port.NewCells()
	var scratch *port.Cells = port.NewCells()
	oneRequest(r, id)
	ocrengine.OeTagFb(r, scratch, routed, ofall.FbSlotRead(), ofall.FbSlotSpec())
	return ocrport.OpRequestEngine(r)
}

