func ftLine(olines *port.Cells, owords *port.Cells, text *port.Cells, x int32, y int32, numeric int32) int32 {
	// One OCR line of one word at (x, y), 40 wide and 20 high: `6.50` when `numeric` is 1, `abc` else.
	var tstart int32 = port.CellsLen(text)
	var w int32 = evidence.OwCount(owords)
	if numeric == 1 {
		port.CellsPush(text, 54)
		port.CellsPush(text, 46)
		port.CellsPush(text, 53)
		port.CellsPush(text, 48)
	} else {
		port.CellsPush(text, 97)
		port.CellsPush(text, 98)
		port.CellsPush(text, 99)
	}
	evidence.OwNew(owords, 1, x, y, x+40, y+20, x, y, x+40, y+20, 0, 0, tstart, port.CellsLen(text)-tstart, evidence.OlCount(olines), 800, 0)
	evidence.OlNew(olines, 1, x, y, x+40, y+20, x, y, x+40, y+20, 0, 0, w, 1)
	return 0
}

func ftRows(olines *port.Cells, owords *port.Cells, text *port.Cells, rows int32, cols int32, numericCols int32, jitter int32) int32 {
	// `rows` rows of `cols` lines, the first `numeric-cols` numeric; the lines of a row are `jitter` points out of true by turns.
	var r int32 = 0
	var c int32 = 0
	var num int32 = 0
	for r < rows {
		c = 0
		for c < cols {
			num = 0
			if c < numericCols {
				num = 1
			}
			ftLine(olines, owords, text, 50+(c*100), (100+(r*40))+(jitter*((2*(c-(2*(c/2))))-1)), num)
			c += 1
		}
		r += 1
	}
	return 0
}

func formOf(rows int32, cols int32, numericCols int32, jitter int32, receipt int32) int32 {
	var olines *port.Cells = port.NewCells()
	var owords *port.Cells = port.NewCells()
	var text *port.Cells = port.NewCells()
	var scr *port.Cells = port.NewCells()
	ftRows(olines, owords, text, rows, cols, numericCols, jitter)
	return ofall.FbForm(olines, owords, text, 0, rows*cols, receipt, scr)
}

func TestAPageOfRowsOfNumbersIsAFormAndAReceiptOrProseIsNot(emonT *testing.T) {
	port.AssertEq(emonT, ofall.FbFormRows(), 6, "six rows make a form")
	port.AssertEq(emonT, ofall.FbFormLines(), 12, "of at least a dozen lines")
	port.AssertEq(emonT, formOf(8, 4, 2, 0, 0), 8, "eight rows of four lines, two of them numbers: a statement")
	port.AssertEq(emonT, formOf(8, 4, 2, 3, 0), 8, "the lines of a row a few points out of true are still one row")
	port.AssertEq(emonT, formOf(6, 3, 3, 0, 0), 6, "exactly six rows of three numeric lines")
	port.AssertEq(emonT, formOf(5, 4, 2, 0, 0), 0, "five rows are not a form")
	port.AssertEq(emonT, formOf(8, 4, 2, 0, 1), 0, "a page kin took for a receipt is never a form, whatever its rows")
	port.AssertEq(emonT, formOf(8, 4, 1, 0, 0), 0, "rows with one number are not a table of numbers")
	port.AssertEq(emonT, formOf(8, 4, 0, 0, 0), 0, "columns of prose are not a form")
	port.AssertEq(emonT, formOf(8, 2, 2, 0, 0), 0, "rows of two lines are not tabular enough")
	port.AssertEq(emonT, formOf(3, 3, 3, 0, 0), 0, "nine lines are too few to say")
}

